      current_statement__ = 5;
      stan::io::read_from_context(mu_a2, context__, "mu_a2");
      out__.write(mu_a2);
      local_scalar_t__ sigma_a1 = DUMMY_VAR__;
      current_statement__ = 6;
      stan::io::read_from_context(sigma_a1, context__, "sigma_a1");
      out__.write_free_lub(0, 100, sigma_a1);
      local_scalar_t__ sigma_a2 = DUMMY_VAR__;
      current_statement__ = 7;
      stan::io::read_from_context(sigma_a2, context__, "sigma_a2");
      out__.write_free_lub(0, 100, sigma_a2);
      local_scalar_t__ sigma_y = DUMMY_VAR__;
      current_statement__ = 8;
      stan::io::read_from_context(sigma_y, context__, "sigma_y");
      out__.write_free_lub(0, 100, sigma_y);
